csui.define('d2/controls/overflow.tooltip/overflow.tooltip',[
  'nuc/lib/jquery'
], function($){
  'use strict';

  var JQ_EVENTS = 'mouseenter.d2_overflow_tooltip mouseleave.d2_overflow_tooltip',
    DATA_ATTR_NAME = 'data-d2-overflow-tooltip',
    EL_SELECTOR = '[' + DATA_ATTR_NAME + '], .d2-overflow-tooltip, .d2-overflow-tooltip>*';

  function showOrHideDefaultTooltipIfTextOverflows(event) {
    var $el = $(event.target),
      el = $el[0],
      tooltipValue = $el.attr(DATA_ATTR_NAME) || $el.text(),
      title = $el.attr('title');

    if (!title && (event.type === 'mouseenter')) {
      if (el.offsetWidth < el.scrollWidth) {
        var attrs = {'title': tooltipValue};
        attrs[DATA_ATTR_NAME] = tooltipValue;

        $el.attr(attrs);
        $el.data('d2OverflowTooltip', true);
      }
    } else if(((event.type === 'mouseleave') || (el.offsetWidth >= el.scrollWidth)) && (title === tooltipValue) && ($el.data('d2OverflowTooltip') === true)){
      $el.removeAttr('title');
    }
  }

  $(document).off(JQ_EVENTS).on(JQ_EVENTS, EL_SELECTOR, showOrHideDefaultTooltipIfTextOverflows);
});

csui.define('d2/overrides/smart/controls/progresspanel/progresspanel.wrapper.view',[
  "smart/controls/progresspanel/progresspanel.wrapper.view",
  'csui/controls/form/pub.sub'
], function ( ProgressPanelWrapperView, PubSub) {
  'use strict';

  var oldMakeStackPanels = ProgressPanelWrapperView.prototype._makeStackPanels;

  ProgressPanelWrapperView.prototype._onProcessPending = function () {
    this.$el?.find(".csui-minimize")?.removeClass("binf-hidden");
    this.$el?.hasClass("smart-expanded") &&
    this.$el?.find(".showless")?.removeClass("binf-hidden");
    this.$el?.find(".d2-minimize-progresspanel").length>0?this.$el?.find(".closeall")?.addClass("binf-hidden")
  : this.$el?.find(".closeall")?.addClass("smart-hide-behind");
  };

  ProgressPanelWrapperView.prototype._onAllProcessCompleted = function () {
    PubSub.trigger('d2-all-process-completed');
    this.$el?.find(".csui-minimize")?.addClass("binf-hidden");
    this.$el?.hasClass("smart-expanded") && this.$el?.find(".showless")?.removeClass("binf-hidden");
    if (this.$el?.find(".d2-minimize-progresspanel").length > 0) {
      this.$el?.find(".closeall")?.addClass("smart-hide-behind");
    } else {
      this.$el?.hasClass("smart-expanded") && this.$el?.find(".closeall").removeClass("smart-hide-behind");
    }
  };

  ProgressPanelWrapperView.prototype._makeStackPanels = function(){
    oldMakeStackPanels.apply(this, arguments);
    if(this.stackProgressPanels?.length > 1 && this.$el.hasClass('smart-expanded')){
      this.ui.showMoreBtn.addClass('smart-hide-behind');
    }
  }
});

csui.define('d2/overrides/smart/controls/bulk.selection/bulk.selection.count.label.view',[
    "smart/controls/bulk.selection/bulk.selection.count.label.view"
], function ( BulkSelectionCountLabelView) {
    'use strict';

    BulkSelectionCountLabelView.prototype.updateCounter = function () {
        const updatedCount = this.collection.length;
        this.ui?.selectedCountValue?.prop && this.ui?.selectedCountValue?.prop('value', updatedCount.toString());
        if(updatedCount === 0){
            this.el?.classList?.add('binf-hidden');
            return;
        }
        this.el?.classList?.contains('binf-hidden') && this.el?.classList?.remove('binf-hidden');
    };
});

csui.define('d2/overrides/smart/controls/error/error.view',["nuc/lib/jquery", "nuc/lib/underscore", "i18n", "smart/controls/error/error.view", "smart/themes/theming"], function ($, _, i18n, ErrorView, theming) {
  var proto = ErrorView.prototype, origErrorUiElements = proto.ui, origErrorEvents = proto.events, currentPopoverTarget = null;
  _.extend(proto, {
    ui: _.extend(origErrorUiElements, {
      iconArea: ".csui-error-icon-parent"
    }),
    events: _.extend(origErrorEvents, {
      "focusout @ui.showMoreBtnArea": "_hidePopoverAction"
    }),
    initialize: function () {
      $("*").on("scroll", this._hidePopoverAction.bind(this));
    },
    onBeforeDestroy: function () {
      $("*").off("scroll", this._hidePopoverAction.bind(this));
    },
    _hidePopoverAction: function () {
      if (currentPopoverTarget) {
        currentPopoverTarget.binf_popover("destroy");
        currentPopoverTarget = null;
      }
    },
    handleShowMoreBtnErrorView: function () {
      const errorSuggestionMessageArea = this.$el.find(".csui-suggestion");
      errorSuggestionMessageArea.addClass("binf-hidden");
      this.ui.detailedMsgArea.addClass("binf-hidden");
      this.ui.showMoreBtnArea.removeClass("binf-hidden");
      theming.isJATOTheme() && this.handleJatoIconSize();
    },
    showMoreErrorInfo: function () {
      if (this.options.model.get("title")) {
        var self = this;
        this.popoverOptions = {
          content: _.str.join(" ", this.options.model.get("suggestion"), this.options.model.get("title")),
          html: true,
          container: $.fn.binf_modal.getDefaultContainer(),
          template: "<div class=\"binf-popover d2-error-info-flyout\" role=\"tooltip\"><div class=\"binf-arrow\"></div><div class=\"binf-popover-content\"></div></div>",
          placement: function () {
            var offset = self.ui.iconArea.offset(), infoWidth = self.ui.iconArea.outerWidth(), calc_width = $(window).width() - (offset.left + infoWidth);
            return i18n.settings.rtl ? offset.left > 260 ? "left" : "right" : calc_width > 260 ? "right" : "left";
          }
        };
        this.ui.iconArea.binf_popover(this.popoverOptions);
        this.ui.iconArea.binf_popover("toggle");
        currentPopoverTarget = this.ui.iconArea;
      }
    }
  });
});


