csui.define('d2/overrides/csui/pages/start/perspective.routing',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'csui/pages/start/perspective.routing',
  'dctmw/server.adaptors/converters/node',
  'i18n!csui/pages/start/nls/lang',
  'i18n!csui/pages/start/impl/nls/lang'
], function (require, $, _, PerspectiveRouting, nodeConverter, publicLang, publicLang2) {
  'use strict';

  var oldInstance = PerspectiveRouting.getInstance;
  var nodeRouter = null;

  csui.require([
    'csui/pages/start/impl/node.perspective.router'
  ], function (NodePerspectiveRouter) {
    PerspectiveRouting.getInstance = function (/*options*/) {
      var instance = oldInstance.apply(this, arguments);
      nodeRouter = _.find(instance._routers, function (router) {
        return router instanceof NodePerspectiveRouter;
      });

      //Removing events set earlier
      nodeRouter.nextNode.off('change:id', nodeRouter._updatePageTitle, nodeRouter);
      nodeRouter.nextNode.off('change:name', nodeRouter._updatePageTitle, nodeRouter);

      //Adding our events
      nodeRouter.listenTo(nodeRouter.nextNode, 'change:id', updatePageTitle);
      nodeRouter.listenTo(nodeRouter.nextNode, 'change:name', updatePageTitle);

      return instance;
    };
  });

  function updatePageTitle() {
    if (!nodeRouter.nextNode.has('name')) {
      document.title = _.str.sformat(publicLang2.NodeLoadingTitle, nodeRouter.nextNode.get('id'));
    } else if (nodeConverter.isFavoritesNode(nodeRouter.nextNode.get('id'))) {
      document.title = _.str.sformat(publicLang.FavoritesNodeTitle, nodeRouter.nextNode.get('type_name'), publicLang.ProductName);
    } else {
      document.title = _.str.sformat(publicLang.NodeTitle, nodeRouter.nextNode.get('name'), nodeRouter.nextNode.get('type_name'), publicLang.ProductName);
    }
    nodeRouter._updateBackToTitle();
  }

});

csui.define('d2/overrides/csui/pages/start/impl/search.perspective.router',[
  'nuc/lib/underscore'
], function (_) {
  'use strict';
  csui.require([
    'csui/utils/contexts/factories/user',
    'csui/pages/start/impl/search.perspective.router',
  ], function (UserModelFactory, SearchPerspectiveRouter) {
    var oldRouteUrl = SearchPerspectiveRouter.prototype.routerURL;

    SearchPerspectiveRouter.prototype.routerURL = function (searchQuery) {
      if (searchQuery && searchQuery.has('forcePerspectiveChange')) {
        searchQuery.unset('forcePerspectiveChange', {silent: true});
      }
      return oldRouteUrl.apply(this, arguments);
    };
    
    SearchPerspectiveRouter.prototype.openSearchPerspective = function (path, query_string) {
      // convert the path made of 'name/value' pairs to {name; value} map
      var name,
        parameters = _.reduce(path.split('/'), function (result, item) {
          if (name) {
            result[name] = item != null ? decodeURIComponent(item).trim() : '';
            name = undefined;
          } else {
            name = decodeURIComponent(item);
          }
          return result;
        }, {});
      
      // we need to activate the new router so the old router does not keep listening
      // to the viewState object changes. Like resetting it for example.
      this.activate(false);
      
      if (!this.restoring) {
        this.initViewStateFromUrlParams(query_string, true);
      }
      
      this._updateSearchQueryPageTitle();
      this._updateSearchFormQueryPageTitle();
      
      var user = this.context.getModel(UserModelFactory);
      user.ensureFetched().then(_.bind(function () {
        // if context is coming from CVS then do 'silent:true' otherwise keep it false , to avoid
        // double call to _fetchSearchPerspective().

        // DTWO-119156 Fix
        // When Adv Search is launched from search results page, due to clearing searchQuery, new results are not fetched
        // Hence moving this inside if block
        if (!(this.searchQuery && this.searchQuery.has('forcePerspectiveChange'))) {
          this.searchQuery.clear({silent: true});
        }

        this.searchQuery.set(parameters, {silent: !!this.searchQuery.get('query_id')});
        if (this.searchForm.get('query_id')) {
          this.searchForm.set(parameters, {silent: !!this.searchForm.get('query_id')});
        }
      }, this));
      
    }
    
  });
});

