          type = constants.Types.ACCESSOR,
          typeName = groupUser ? constants.AccessorType.GROUP :
            (accessorName === 'dm_world' || accessorName === 'dm_owner' || accessorName === 'dm_group') ?
              constants.AccessorType.ROLE : constants.AccessorType.USER;

        model['accessorName'] = model['id'] = accessorName;
        model['basicPermission'] = basicPermission;
        model['extendedPermissions'] = extendedPermissions;
        model['type'] = type;
