csui.define('d2/commands/open.plugins/impl/bravaenterprise/document.merge.view',[
  'module',
  'require',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'nuc/models/node/node.model',
  'nuc/utils/url',
  'csui/utils/contexts/factories/node',
  'dctmw/utils/rest.resources',
  'd2/controls/button.toolbar/button.toolbar.view',
  'd2/utils/constants',
  'd2/commands/viewer/document.merge',
  'd2/dialogs/viewer.markup.selection/select.markup.dialog',
  'd2/utils/content.assist',
  'd2/commands/open.plugins/impl/publish/publish.dialog',
  'd2/utils/format.utils',
  'csui/controls/progressblocker/blocker',
  'hbs!d2/commands/open.plugins/impl/bravaenterprise/document.merge.template',
  'i18n!d2/commands/open.plugins/nls/localized.strings',
  'css!d2/commands/open.plugins/impl/bravaenterprise/document.merge'
], function (module, require, _, Backbone, $, Marionette, NodeModel, Url, NodeModelFactory, RestResources,
             ButtonToolbarView, constants, DocumentMergeCommand, SelectMarkupDialog, ContentAssist,
             PublishDialog, FormatUtils, BlockingView, ViewTemplate, lang) {
  'use strict';

  var moduleConfig = _.defaults(module.config(), {
    basePath: window.sv.config.releaseLocation + window.sv.config.otherBundlesLocation
  });

  var DocumentMergeView = Marionette.ItemView.extend({
    className: 'd2-docmergeview',

    template: ViewTemplate,

    templateHelpers: function () {
      return {
        title: lang.DocMergeTitle,
        closeText: lang.ButtonCloseViewer
      };
    },

    ui: {
      close: '.d2-merge-close',
      toolbar: '.d2-docmerge-toolbar'
    },

    constructor: function DocumentMergeView(options) {
      options.data || (options.data = {});

      if (options.collection) {
        throw 'Collection viewing is not supported yet.';
      }

      this.viewer = null;
      this.nodes = options.previewNodes;
      this._connector = options.model.connector;
      this.selectedMarkup = options.selectedMarkup;

      if (options.blockingParentView) {
        BlockingView.delegate(this, this.options.blockingParentView);
      } else {
        BlockingView.imbue(this);
      }


      Marionette.ItemView.prototype.constructor.call(this, options);
      this.documentMergeCommand = new DocumentMergeCommand();

      this.targetBrowseContainer = this.nodes.at(0).parent;
      this.viewerDocuments = new Backbone.Collection();
      this.setViewerDocuments();

      this.exportCompleteCallBackBind = this.exportCompleteCallBack.bind(this);
      $(window).off('exportDocMergeComplete', this.exportCompleteCallBackBind).on('exportDocMergeComplete', this.exportCompleteCallBackBind);

      this.viewerDocuments.on("add remove", this.viewerDocumentsUpdate.bind(this));

      this.listenTo(options.context, 'sync change:perspective', function() {
        this.onClickClose();
      }.bind(this));
    },

    setViewerDocuments: function () {
      var me = this;
      this.nodes.each(function (node) {
        me.viewerDocuments.add(node);
      });
    },

    viewerDocumentsUpdate: function () {
      if (this.viewerDocuments.length === 0) {
        this.toolbarView.leftButtons.models[1].set("disabled", true);
        this.toolbarView.leftButtons.models[2].set("disabled", true);
        this.toolbarView.leftButtons.models[3].set("disabled", true);
      } else {
        this.toolbarView.leftButtons.models[1].set("disabled", false);
        this.toolbarView.leftButtons.models[2].set("disabled", false);
        this.toolbarView.leftButtons.models[3].set("disabled", false);
      }
    },

    onRender: function () {
      this.ui.close.on('click', _.bind(this.onClickClose, this));
      this._setupToolbarView();
    },

    onClickClose: function () {
      var me = this;
      this.clearMarkupsFromSession().done(function() {
        me.trigger('viewer:close');
        me.destroy();
      });
    },

    _setupToolbarView: function () {
      var region = new Marionette.Region({el: this.ui.toolbar});
      var buttonsConfig = {
        right: [],
        left: [{
          id: 'addDocument',
          className: 'icon',
          iconName: 'csui_action_add32',
          tooltip: lang.AddDocument,
          clickHandler: this.addDocuments.bind(this)
        },
          {
            id: 'removeAll',
            className: 'text-button',
            tooltip: lang.RemoveAll,
            label: lang.RemoveAll,
            showLabel: true,
            clickHandler: this.closeAll.bind(this)
          },
          {
            id: 'mergeAll',
            className: 'text-button',
            tooltip: lang.MergeAll,
            label: lang.MergeAll,
            showLabel: true,
            disabled: false,
            hidden: false,
            clickHandler: this.mergeAllDocuments.bind(this)
          },
          {
            id: 'selectMarkup',
            className: 'text-button',
            tooltip: lang.SelectMarkup,
            label: lang.SelectMarkup,
            showLabel: true,
            clickHandler: this.selectMarkup.bind(this)
          }]
      };

      this.toolbarView = new ButtonToolbarView(buttonsConfig);
      region.show(this.toolbarView);
    },

    onShow: function () {
      this.fetchAndLoadViewer();
    },

    addDocuments: function () {
      var me = this, status = {context: this._connector.context};

      this.targetBrowseContainer.fetch().done(function () {
        ContentAssist.getContentAssistOptions(status).done(function (config) {
          var title = config ? config.label_value : "";
          var includeBrowse = (config && config.properties) ? config.properties.has_browse_assist : true;
          var includeFavorites = (config && config.properties) ? config.properties.has_favorites_assist : false;
          var globalSearch = (config && config.properties) ? config.properties.has_search_assist : false;

          me.displayContentAssist(status, title, includeBrowse, includeFavorites, globalSearch, me.targetBrowseContainer).done(function (selectedNodes) {
            if (me.isNodesSupportDocMerge(selectedNodes)) {
              var nodeCollection = new Backbone.Collection();
              _.each(selectedNodes, function (node) {
                if (!me.viewerDocuments[node.get("id")]) {
                  nodeCollection.add(node);
                }
              });
              me.targetBrowseContainer = selectedNodes[0].parent;

              var options = {nodes: nodeCollection, context: me._connector.context, connector: me._connector};

              var selectMarkupDialog = new SelectMarkupDialog(options);
              selectMarkupDialog.show().done(function (selectedMarkup) {
                me.setSelectedMarkupToSession(selectedMarkup).done(function () {
                  me.selectedMarkup = _.extend(me.selectedMarkup, selectedMarkup);
                  _.each(selectedNodes, function (node) {
                    if (me.viewerDocuments.where({"id": node.get("id")}).length === 0) {
                      me.viewerDocuments.add(node);
                      me.loadDocument(node);
                    }
                  });
                });
              }).fail(function () {

              });
            }
          });
        });

      });

    },

    closeAll: function() {
      var iframe = $('#'+this.viewer.clientId);
      if(iframe.length > 0) {
        var docTopPanes = $(iframe).contents().find(".docTopPane");
        $(docTopPanes).each(function() {
          $(this).find(".closeLink")[0].click();
        });
      }
    },

    mergeAllDocuments: function() {
      var me = this, promises = [];
      this.viewer.clearMergedPages().then(function() {
        me.viewerDocuments.each(function(node) {
          var objId = node.get("id");
          var promise = me.viewer.getLoadedDocumentData({documentId: objId});
          promises.push(promise);
        });
        $.when(promises).then(function(allPromises) {
          if(allPromises.length > 0) {
            for (var x = 0; x < allPromises.length; x++) {
              var y = x.toString();
              me.addPagesToMerge(allPromises[x], y);
            }
          }
        });
      });

    },

    addPagesToMerge: function(promise, docNum) {
      var me = this;
      promise.then(function (val) {
        for (var j = 0;j < val.pages.length; j++) {
          var pgNum = j + 1;
          me.viewer.addPageToMergedDocument({compositionId: val.compositionId, requestIndex: docNum, pageNumber: pgNum});
        }
      })
    },

    displayContentAssist: function (status, title, includeBrowse, includeFavorites, globalSearch, container) {
      var me = this, deferred = $.Deferred();

      csui.require(['d2/dialogs/target.browse/target.browse'], function (NodePicker) {
        var pickerOptions = {
          dialogTitle: title,
          connector: me._connector,
          container: container,
          initialContainer: container,
          context: status.context,
          selectMultiple: true,
          includeBrowse: includeBrowse,
          globalSearch: globalSearch,
          includeFavorites: includeFavorites,
          includeRelatedFiles: false,
          selectType: 'typeName',
          selectTypeValue: constants.Types.DOCUMENT,
          disableContentTypes: me.documentMergeCommand.getAllNotSupportedContentTypes(false)
        };

        pickerOptions.storeContainer = true;
        pickerOptions.restoreContainer = true;
        pickerOptions.dataId = constants.StorageKey.DOCUMENT_MERGE_VIEW + constants.StorageKey.ANCESTOR_INFO;

        if (!pickerOptions.dialogTitle || pickerOptions.dialogTitle.length === 0) {
          pickerOptions.dialogTitle = lang.TargetBrowseTitle;
        }
        pickerOptions.startLocations = [];
        if (pickerOptions.includeBrowse) {
          pickerOptions.startLocations.push('current.location');
        }
        if (pickerOptions.includeFavorites) {
          pickerOptions.startLocations.push('favorites');
        }
        var nodePicker = new NodePicker(pickerOptions);

        nodePicker.show().done(function (selectedNodes) {
          deferred.resolve(selectedNodes.nodes);
        }).fail(function () {
          deferred.reject('close');
        });
      }, deferred.reject);

      return deferred.promise();
    },

    selectMarkup: function () {
      var me = this;
      if (this.viewerDocuments.length === 0) {
        return;
      }
      var options = {
        nodes: this.viewerDocuments,
        context: this._connector.context,
        connector: this._connector,
        selectedMarkup: this.selectedMarkup
      };

      var selectMarkupDialog = new SelectMarkupDialog(options);
      selectMarkupDialog.show().done(function (selectedMarkup) {
        me.selectedMarkup = selectedMarkup;
        var objectKeys = _.keys(selectedMarkup);
        var markupCount = 0;
        _.each(objectKeys, function (docId) {
          markupCount += selectedMarkup[docId].length;
        });
        if(markupCount > 0) {
          me._loadViewer();
        }
      }).fail(function () {

      });
    },

    isNodesSupportDocMerge: function (selection) {
      if (selection.length !== 0) {
        var nodeCollection = new Backbone.Collection();
        _.each(selection, function (node) {
          nodeCollection.add(node);
        });

        var status = {
          nodes: nodeCollection
        };
        var documentMergeEnable = this.documentMergeCommand.enabled(status);

        return documentMergeEnable;
      }
      return false;
    },

    fetchAndLoadViewer: function () {
      var me = this,
        currentRepo = RestResources.getCurrentRepository().get('name'),
        currentUser = RestResources.getCurrentUser().get('name'),
        documentId = me.model.get('id'),
        tzoffset = FormatUtils.getTimezoneOffset(),
        href = Url.combine(me._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "getClientLoadData"),
        qParams = {
          repo: currentRepo,
          log: currentUser,
          docid: documentId,
          tzoffset: tzoffset
        };

      href = Url.appendQuery(href, Url.combineQueryString(qParams));

      this.blockActions();

      $.ajax(me._connector.extendAjaxOptions({
        url: href,
        type: 'GET',
        success: function (data) {
          data = JSON.parse(data);
          me.isCrossOrigin = data.isCrossOrigin;
          me.corsServersEntries = data.corsServersEntries;
          me.unblockActions();
          me._loadViewer();
        },
        error: function (error) {
          me.unblockActions();
          me.destroy();
          if (error.message) {
            csui.require([
              'd2/controls/globalmessage/globalmessage'
            ], function (GlobalMessage) {
              GlobalMessage.showMessage("error", error.message, undefined, {});
            });
          }
        }
      }));
    },

    _loadViewer: function () {
      var me = this, currentUser = RestResources.getCurrentUser().get('name'),
        signConfigUrl = this._getHtmlViewerSignConfigUrl();

      $(this.el).find(".d2-bravadocmergeviewer").html("");

      this.setSelectedMarkupToSession(this.selectedMarkup).done(function () {
        csui.require([
          'igc/HTML/html-clients'
        ], function loadScripts() {
          csui.require([
            'igc/DocMerge/viewer/docmerge'
          ], function loadScripts() {

            var dmClient = window.brava.htmlClients.create("docmerge", {
              clientType: "docmerge",
              path: moduleConfig.basePath + '/igc/DocMerge/viewer',
              container: "d2-bravadocmergeviewer",
              showCloseButton: false,
              userName: currentUser,
              logLevel: "all",
              nodeType: "iframe",
              isCrossOrigin: me.isCrossOrigin,
              corsServersEntries: me.corsServersEntries,
              height: "100%",
              width: "100%",
              signedConfigUrl: signConfigUrl,
              xmlPostType: "text/xml",
              requestHeaders: me._getSharedHeaderParams(),
              useCompatibilityPrint: true,
              ui: {},
              onDocumentExport: 'fire-event'
            });

            dmClient.apiPromise.then(function (api) {
              me.viewer = api;
              me.viewerDocuments.each(function (node) {
                me.loadDocument(node);
              });

              api.on('DocMergeClosed', function () {
                me.trigger('viewer:close');
                me.destroy();
              });
              api.on('DocumentClosed', function (data) {
                me.unloadDocument(data);
              });
            });
          }, function () {
            me._onViewerApiError("HTML Client file load failed");
          });

        }, function () {
          me._onViewerApiError("HTML Client file load failed");
        });
      });

    },

    loadDocument: function (node) {
      this.viewer.loadDocument({
        title: node.get("title"),
        documentId: node.get("id"),
      });
    },

    unloadDocument: function (data) {
      var documentId = data.content.documentId;
      var node = this.viewerDocuments.where({"id": documentId});
      delete this.selectedMarkup[documentId];
      this.viewerDocuments.remove(node);
    },

    setSelectedMarkupToSession: function (selectedMarkup) {
      var me = this,
        currentRepo = RestResources.getCurrentRepository().get('name'),
        href = Url.combine(me._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "docmerge", "markup-selection"),
        markupData = {
          "selectedMarkUpAndDocument": []
        };

      var objectKeys = _.keys(selectedMarkup);

      _.each(objectKeys, function (docId) {
        markupData.selectedMarkUpAndDocument.push({
          "documentId": docId,
          "markUps": selectedMarkup[docId]
        });
      });


      return $.ajax(me._connector.extendAjaxOptions({
        url: href,
        type: 'POST',
        contentType: constants.MediaTypes.DCTM_JSON,
        data: JSON.stringify(markupData),
      }));
    },

    clearMarkupsFromSession: function () {
      var currentRepo = RestResources.getCurrentRepository().get('name'),
        href = Url.combine(this._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "docmerge", "markup-selection", "clear");

      return $.ajax(this._connector.extendAjaxOptions({
        url: href,
        type: 'DELETE',
        contentType: constants.MediaTypes.DCTM_JSON,
      }));
    },

    _getHtmlViewerSignConfigUrl: function () {
      var currentUser = RestResources.getCurrentUser().get('name'),
        currentRepo = RestResources.getCurrentRepository().get('name'),
        tzoffset = FormatUtils.getTimezoneOffset(),
        url = Url.combine(this._connector.connection.url, "repositories", currentRepo, "bravaenterprise", "docmerge", "signconfig");

      var qParams = {
        repo: currentRepo,
        log: currentUser,
        tzoffset: tzoffset
      };

      return Url.appendQuery(url, Url.combineQueryString(qParams));
    },

    _getSharedHeaderParams: function () {
      var headers = {};
      this.model.connector.authenticator.setAuthenticationHeaders(headers);
      return headers;
    },

    _onViewerApiError: function (error) {
      this.trigger('viewer:error', error);
    },

    reloadViewer: function () {
      this.fetchAndLoadViewer();
    },

    exportCompleteCallBack: function (e) {
      this.showPublishDialog(e);
    },

    showPublishDialog: function(e) {
      $(this.el).parents(".csui-full-page-modal").css("z-index", "1044");
      var dialog = new PublishDialog({
        publishUrl: e.detail.url,
        type: e.detail.type.toLowerCase(),
        node: this.model,
        context: this._connector.context,
        addExtraOptions: [],
        defaultFileName: ''
      });
      dialog.show();
    },

    onDestroy: function () {
      $(window).off('exportDocMergeComplete', this.exportCompleteCallBackBind);
    },

  });

  return DocumentMergeView;
});

csui.define('css!d2/commands/open.plugins/impl/iviewer/default',[],function(){});

csui.define('d2/commands/open.plugins/impl/iviewer/default.view',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'csui/utils/contexts/factories/node',
  'd2/utils/rest.linkrels',
  'dctmw/utils/rest.resources',
  'dctmw/dialogs/authentication/oauth.login.dialog',
  'nuc/utils/log',
  'nuc/utils/url',
  'd2/controls/behaviors/viewer.masking.behavior',
  'csui/dialogs/modal.alert/modal.alert',
  'csui/controls/globalmessage/globalmessage',
  'csui/controls/progressblocker/blocker',
  'd2/utils/server.query.utils',
  'd2/utils/widget.constants',
  'd2/commands/open.plugins/impl/iviewer/utils',
  'd2/commands/open.plugins/impl/viewer.utils',
  'd2/commands/download',
  'csui/utils/commands',
  'd2/commands/open.plugins/impl/publish/publish.fields.constant',
  'd2/commands/open.plugins/impl/markup.migration/view',
  'i18n!d2/commands/open.plugins/nls/localized.strings',
  'css!d2/commands/open.plugins/impl/iviewer/default'
], function (_, $, Marionette, NodeModelFactory, RestLinkrels, RestResources, OAuthLoginDialog,
             log, Url, ViewerMaskingBehavior, ModalAlert, GlobalMessage, BlockingView, serverQueryUtils,
             widgetConstants, iViewerUtils, viewerUtils, DownloadCommand, commands, PublishFieldsConstant,
             MarkupMigrationView, lang) {
  'use strict';

  var ivWidgetConfiguration,
    intelligentViewerConfig,
    isIVAnnotateDisabled,
    layout,
    userDefaultWidgets,
    userLanguage,
    currentUser = RestResources.getCurrentUser();

  if (currentUser && !_.isEmpty(currentUser)) {
    userDefaultWidgets = currentUser.get('defaultWidgets');
    userLanguage = currentUser.get('preferences')['default_language'];
  }
  if (userDefaultWidgets && !_.isEmpty(userDefaultWidgets)) {
    ivWidgetConfiguration = serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAIV, userDefaultWidgets[widgetConstants.DEFAULT.BRAVAIV]);
  }
  if (ivWidgetConfiguration && !_.isEmpty(ivWidgetConfiguration)) {
    intelligentViewerConfig = JSON.parse(ivWidgetConfiguration.widgetParams["brava_iv_configuration"]);
    isIVAnnotateDisabled = ivWidgetConfiguration.widgetParams["is_brava_iv_disable_annotate"];
  }
  if (isIVAnnotateDisabled) {
    var removeAnnotationFeature = intelligentViewerConfig.leftTabContainer && intelligentViewerConfig.leftTabContainer.tabs;
    removeAnnotationFeature = removeAnnotationFeature.filter(function (value/*, index, arr*/) {
      if (_.contains(['MarkupPane', 'StampRasterPane', 'TakeoffPane'], value.component)) {
        return false;
      } else {
        return true;
      }
    });
    intelligentViewerConfig.leftTabContainer.tabs = removeAnnotationFeature;
  }
  if (intelligentViewerConfig && !_.isEmpty(intelligentViewerConfig)) {
    layout = _.defaults(
      {
        topToolbar: 'toolbarWithMarkupStuff',
        toolbarWithMarkupStuff: intelligentViewerConfig.toolbarWithMarkupStuff,
        mainContainer: [
          {component: 'TabContainer', layoutKey: 'leftTabContainer'},
          {component: 'PageContainer'}
        ]
      }, intelligentViewerConfig);
  }

  var viewerClassName = 'd2-bravaintelligentviewer';
  var appleMatches = navigator.userAgent.match(/(iPad)/i);
  if (appleMatches) {
    viewerClassName = 'd2-brava-iviewer-ipad';
  }

  if (userLanguage && !_.isEmpty(userLanguage)) {
    window.___BRAVA_LOCALE___ = userLanguage;
  }

  return Marionette.ItemView.extend({
    className: viewerClassName,

    template: _.template('<div id="migrationInfo" class="migration-info binf-hidden"></div><div id="bravaViewRoot" class="d2-iv-viewer-div"></div>'),

    behaviors: {
      MaskingBehavior: {
        behaviorClass: ViewerMaskingBehavior
      }
    },

    constructor: function DefaultViewer(options) {
      if (options == null) {
        log.error("OpenText Intelligent Viewing options is missing");
        return;
      }
      if (!options.model) {
        options.model = options.context.getModel(NodeModelFactory, {
          attributes: {
            id: options.data.id,
            version_number: options.data.version_number
          }
        });
      }
      this.ivWidgetName = null;
      if (userDefaultWidgets && !_.isEmpty(userDefaultWidgets) && !_.isEmpty(userDefaultWidgets[widgetConstants.DEFAULT.BRAVAIV])) {
        this.ivWidgetName = userDefaultWidgets[widgetConstants.DEFAULT.BRAVAIV];
      }
      Marionette.ItemView.prototype.constructor.call(this, options);
      this.isPreviewMode = options.isPreviewMode;
      this.isEmbeddedPreview = options.isEmbeddedPreview ? options.isEmbeddedPreview : false;

      if (this.options.blockingParentView) {
        BlockingView.delegate(this, this.options.blockingParentView);
      } else {
        BlockingView.imbue(this);
      }
      this.api = null;
      this.publicationIdToDocumentId;
      this.isExpanded = false;
      this.nodes = options.previewNodes;

      this.listenTo(this.model, 'change', this.onChangeModel);

      this.listenTo(this, 'panel:expand', function () {
        this.isExpanded = true;
        this.showCollapseViewerButton();
      }.bind(this));
      this.listenTo(this, 'panel:collapse', function () {
        this.isExpanded = false;
        this.showExpandViewerButton();
      }.bind(this));

      this.viewerId = _.uniqueId('viewer_');
      this.migrationStatusId = _.uniqueId('migration_');
      this.isRelatePermission = false;

      this.initIntelligentViewerConfig();
      this.listenTo(options.context, 'sync change:perspective', function() {
        this.isAppliedMask() && this.trigger('remove:mask');
        this.clearViewer();
      }.bind(this));
      if(this.isPreviewMode) {
        !this.isAppliedMask() && this.trigger('apply:mask');
      }
    },

    ui: {
      markupMigration: '#migrationInfo'
    },

    initIntelligentViewerConfig: function () {
      this.bearerToken = null;
      this.bravaIVConfiguration = null;
      this.currentPageConfig = null;
      this.bravaReadyEventCallBackBind = this.bravaReadyEventCallBack.bind(this);

      $(window).off('bravaReady', this.bravaReadyEventCallBackBind).on('bravaReady', this.bravaReadyEventCallBackBind);

    },

    bravaReadyEventCallBack: function (e) {
      if(this.currentPageConfig) {
        return;
      }
      var me = this;
      this.currentPageConfig = e.detail;
      $("body").addClass("ot-iviewer-overflow");
      this.setViewerConfig();

      if(this.isPreviewMode) {
        if (this.isEmbeddedPreview) {
          $(this.el).addClass('d2-embedded-preview');
          this.api.hideToolbarButtons(['popInViewerButtonButton', 'expandViewerButtonButton', 'collapseViewerButtonButton']);
        }
        else {
          this.api.hideToolbarButtons(['popInViewerButtonButton', 'popOutViewerButtonButton', 'collapseViewerButtonButton']);
          this.isExpanded && this.showCollapseViewerButton();
        }
      }
      else {
        this.api.hideToolbarButtons(['popInViewerButtonButton', 'popOutViewerButtonButton', 'expandViewerButtonButton', 'collapseViewerButtonButton']);
        this.options.showCollapseButton && this.api.unhideToolbarButtons(['popInViewerButtonButton']);
      }
      // called from onShow
      this.getPublicationDeferred.done(function(response) {
        me.addPublication(response);
        me.unblockActions();
      })
        .fail(function() {
          me._pageRendered();
          me.destroy();
        });
    },

    _closeEvent: function (e) {
      this.migrationStatusTimer && clearInterval(this.migrationStatusTimer);
      this.checkDirtyMarkupAndCloseOrPopOut(e, true);
    },

    _doClose: function(e) {
      this.isAppliedMask() && this.trigger('remove:mask');
      this.trigger('viewer:close', e);
      if(this.isEmbeddedPreview){
        return;
      }
      if(this.needMarkupCountUpdate) {
        this.updateMarkupCountForNodes();
      }
      if(this.isPreviewMode) {
        if(this.isExpanded) {
          this.trigger('overlay:panel:collapse');
          this.isExpanded = false;
          this.showExpandViewerButton();
        }
        this.clearViewer();
        return;
      }
      this._setPredicates(false);
    },

    updateMarkupCountForNodes: function() {
      var def = $.Deferred();
      if (this.nodes && this.nodes.models && this.nodes.models.length > 0) {
        var nodeIds = _.chain(this.nodes.models).pluck('attributes').pluck('id').value();
        iViewerUtils.getMarkupCounts(this.model.connector, nodeIds).done(function(data) {
          this.nodes.trigger("update:viewer:markup:count", data.markupCount);
          this.needMarkupCountUpdate = false;
          def.resolve();
        }.bind(this), function (error) {
          def.reject(error);
        });
      } else {
        def.resolve().promise();
      }
      return def.promise();
    },

    onRender: function() {
      $(this.el).find('.d2-iv-viewer-div').attr('id', this.viewerId);
      $(this.el).find('.migration-info').attr('id', this.migrationStatusId);
      this.pageUnloadBind = this._pageUnloadEvent.bind(this);
      this.container = $(this.el).find("#" + this.viewerId);
      this.container.on('markupsDirty', this._markupsDirtyEvent.bind(this));

      this.container.on('close', this._closeEvent.bind(this));
      this.container.on('pageRender', this._pageRendered.bind(this));
      this.container.on('markupFeaturesAvailable', this._markupFeaturesAvailableEvent.bind(this));
      this.container.on('exportSuccess-download', this._exportSuccessDownloadEvent.bind(this));
      this.container.on('expandViewerButtonClick', this._expandViewerButtonClickEvent.bind(this));
      this.container.on('popOutViewerButtonClick', this._popOutViewerButtonClickEvent.bind(this));
      this.container.on('popInViewerButtonClick', this._popInViewerButtonClickEvent.bind(this));
      this.container.on('collapseViewerButtonClick', this._collapseViewerButtonClickEvent.bind(this));
      this.container.on('svgPageLoadFailure', this._svgPageLoadFailureEvent.bind(this));
      $(window).on('beforeunload', this.pageUnloadBind);
    },

    _pageUnloadEvent: function(/*e*/) {
      if(this.isDirtyMarkup) {
        return true;
      }
    },

    onBeforeDestroy: function () {
      $(this.el).html('');
      $(window).off('bravaReady', this.bravaReadyEventCallBackBind);
      $(window).off('beforeunload', this.pageUnloadBind);
      $("body").removeClass("ot-iviewer-overflow");
      this.isAppliedMask() && this.trigger('remove:mask');
    },

    _pageRendered: function () {
      this.unblockActions();
      this.trigger('viewer:init');
      this._setPredicates(!this.isAnnotateDisabled());
    },

    _setPredicates : function(isEnabled) {
      var me = this;

      this.api.commentableMarkupPredicate = function (/*markup*/) {
        return isEnabled;
      };
      this.api.editableMarkupPredicate = function(markup) {
        return me._canPredicate(markup, isEnabled);
      };

      this.api.deletableMarkupPredicate = function(markup) {
        return me._canPredicate(markup, isEnabled);
      };

      this.api.deletableStampPredicate = function (stamp) {
        return me._canPredicate(stamp, isEnabled);
      };

      this.api.editableStampPredicate = function (stamp) {
        return me._canPredicate(stamp, isEnabled);
      };

      this.api.addableStampPredicate  = function (/*stamp*/) {
        return isEnabled;
      };

      this.api.visibleCommandPredicate = function(key) {
        if (key === 'addToNewStamp') {
          return isEnabled;
        }
      };
    },

    _canPredicate : function (feature, isEnabled){
      if(!isEnabled) {
        return false;
      }
      return feature.author === RestResources.getCurrentUser().get('name');
    },

    _markupFeaturesAvailableEvent: function () {
      if(intelligentViewerConfig && intelligentViewerConfig.imageRaster) {
        this.api.addRasters(intelligentViewerConfig.imageRaster);
      }
    },

    _svgPageLoadFailureEvent: function (/*e*/) {
      this.unblockActions();
      this.reloadViewer();
    },

    _exportSuccessDownloadEvent: function (e) {
      if (e) {
        var loadSourcesProp, loadSources, sourceDocName, artifact, exportType, urlTemplate, content,
            url, downloadFileName;
        loadSourcesProp = Object.keys(e.detail._embedded['otc:get_configs_id'].features).filter(
          function (property) {
            return property.startsWith('opentext.publishing.sources@LoadSources@')
          });
        loadSources = loadSourcesProp ? Object.values(e.detail._embedded['otc:get_configs_id'].features[loadSourcesProp].documents) : undefined;
        sourceDocName = loadSources ? loadSources[0].filenameHint : undefined;

        artifact = e.detail._embedded['pa:get_publication_artifacts'][0]._embedded['ac:get_artifact_content'];

        if (artifact) {
          exportType = artifact.acceptHint ? artifact.acceptHint === 'application/pdf' ? 'pdf' : 'tiff' : '';
          urlTemplate = artifact.urlTemplate;
          content = artifact.contentLinks[0]
        }
        if (urlTemplate) {
          url = urlTemplate
            .replace('{id}', content.id)
            .replace('{name}', content.name)
            .replace('{type}', content.type)
            .replace('{file}', content.file);
        }
        if (sourceDocName) {
          downloadFileName = sourceDocName.replace(loadSources[0].formatHint, exportType);
        }
        if (url) {
          const me = this;
          const { context, model } = me.options;
          const publishCommand = commands.get('D2-PublishTo');
          const fileSize = e.detail.tags?.[1]?.__sizeInBytes || 0;

          const hideOptions = new Set();

          const pushOptions = (...options) => {
            options.forEach(opt => hideOptions.add(opt));
          };

          const clientCapability = me?.options?.context?._user?.attributes?.properties?.client_capability;
          const publishOpts = PublishFieldsConstant.publishOptions;

          if (clientCapability === 1) {
            pushOptions(
              publishOpts.NEW_FILE,
              publishOpts.VERSION,
              publishOpts.RENDITION
            );
          }

          viewerUtils.checkAndHideOption(model, 'AddVersion', publishOpts.VERSION, hideOptions);
          viewerUtils.checkAndHideOption(model, 'D2-AddRendition', publishOpts.RENDITION, hideOptions);
          viewerUtils.checkAndHideOption(model, 'Download', publishOpts.DOWNLOAD, hideOptions);

          if (hideOptions.size === 4) {
            csui.require(['smart/dialogs/modal.alert/modal.alert'], function (alertDialog) {
              alertDialog.showWarning(
                lang.PermissionWarningText,
                lang.PermissionWarningTitle,
                {
                  buttons: {
                    ok: {
                      label: lang.OkButtonLabel
                    }
                  }
                }
              );
            });
          } else {
            publishCommand.execute(
              {
                context,
                nodes: model,
                originatingView: ''
              },
              {
                docUrl: url,
                docDownloadFileName: downloadFileName,
                exportType,
                bearerToken: this.bearerToken,
                size: fileSize,
                hideOption: [...hideOptions]
              }
            );
          }
        }
      }
    },

    _expandViewerButtonClickEvent: function (e) {
      this.trigger('overlay:panel:expand', e);
      this.showCollapseViewerButton();
      //Todo: global variable is not required on custom close
      this.isExpanded = true;
    },

    _collapseViewerButtonClickEvent: function (e) {
      this.trigger('overlay:panel:collapse', e);
      this.showExpandViewerButton();
      //Todo: global variable is not required on custom close
      this.isExpanded = false;
    },

    _popOutViewerButtonClickEvent: function(e) {
      this.checkDirtyMarkupAndCloseOrPopOut(e, false);
    },

    _popInViewerButtonClickEvent: function(e) {
      this.checkDirtyMarkupAndCloseOrPopOut(e, true);
    },

    checkDirtyMarkupAndCloseOrPopOut: function(e, close) {
      var me = this;
      if(this.isDirtyMarkup) {
        this.showSaveMarkupDialog().done(function(/*data*/) {
          me.api.save();
          $("body").find('#ot-iv-tool-properties').hide();
          close ? me._doClose(e) : me._doPopOut(e);
        }).fail(function() {
          me.api.restoreToLastSave();
          me.isDirtyMarkup = false;
          me.isAppliedMask() && me.trigger('remove:mask');
          $("body").find('#ot-iv-tool-properties').hide();
          close ? me._doClose(e) : me._doPopOut(e);
        });
      }
      else {
        $("body").find('#ot-iv-tool-properties').hide();
        close ? me._doClose(e) : me._doPopOut(e);
      }
    },

    _doPopOut: function(e) {
      this.trigger('viewer:expand', e);
    },

    setPublicationToViewer: function () {
      var me = this, deferred = $.Deferred();
      this.blockActions();
      this._getPublication().done(function (response) {
        me.addPublication(response);
        deferred.resolve();
      }).fail(function () {
        me.destroy();
        deferred.reject();
      }).always(function(){
        me.unblockActions();
      });
      return deferred.promise();
    },

    //Need to override
    addPublication: function(response) {
      var publication = JSON.parse(response);
      if (publication.status === 'Failed') {
        this._pageRendered();
        GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
      }
      else {
        var documentId = this.model.get('id');
        this.documentIdAdded = documentId;
        this.api.addPublication(publication, true, documentId);
        setTimeout(function() {
          this.checkForMigration(this.model.connector, [documentId]);
        }.bind(this), 1000)
      }
    },

    setViewerConfig: function () {
      this.api = window[this.currentPageConfig];
      this.api.setAutoRender(false);
      this.setLayout();
      this.api.setHttpHeaders({'Authorization': this.bearerToken});
      this.api.setSearchHost(this.bravaIVConfiguration.brava_highlight_service_url);
      this.api.setMarkupHost(this.bravaIVConfiguration.brava_markup_service_url);
      this.api.setUserName(RestResources.getCurrentUser().get('name'));
      this.api.enableMarkup(true);
      this.api.setActiveTab("tab.thumbnails");
      const watermark = this.getWidgetParamText("brava_iv_watermark_text");
      if (watermark) {
        this.api.setScreenWatermark(watermark);
      }
      const banner = this.getWidgetParamText("brava_iv_banner_text");
      if (banner) {
        this.api.setScreenBanner(banner);
      }
      this.api.setDBStringResolver(this.resolveDBString.bind(this));
      this.api.render(this.viewerId);
    },

    getWidgetParamText: function (key) {
          return ivWidgetConfiguration?.widgetParams?.[key] || null;
    },

    resolveDBString: function (tokens, publicationId) {
          const deferred = $.Deferred();
          const documentId = this.publicationIdToDocumentId[publicationId];

          if (!documentId) {
            return deferred.resolve(Object.fromEntries(tokens.map(token => [token, "[MISSING]"]))).promise();
          }
          const models = this.options?.previewNodes?.models;
          const node = (Array.isArray(models) && models.length > 1)? _.find(models, m => m.get('id') === documentId) : this.model;
          return deferred.resolve(Object.fromEntries(tokens.map(token => [token, node?.get(token) != null ? String(node.get(token)) : "[MISSING]"]))).promise();
    },

    addComparePublications: function(response, compareType) {
      if (!response || !Array.isArray(response.publications)) {
        this._pageRendered();
        GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
        this.destroy();
        return;
      }

      let leftPublication = null;
      let rightPublication = null;
      let publicationError = null;

      this.publicationIdToDocumentId = {};

      response.publications.forEach((pubStr, index) => {
        try {
          const publication = JSON.parse(pubStr);
          const isFailed = publication.status === 'Failed' || !!publication.publicationErrorForFile;

          if (isFailed) {
            publicationError = publication.publicationErrorForFile || null;
          } else {
            const docId = this.nodes.at(index)?.get('id');
            this.publicationIdToDocumentId[publication.id] = docId;

            if (index === 0) {
              leftPublication = publication;
            } else if (index === 1) {
              rightPublication = publication;
            }
          }
        } catch (e) {
          publicationError = lang.IVDocumentLoadError;
        }
      });

      if (!leftPublication || !rightPublication) {
        this._pageRendered();
        const errorMessage = publicationError
          ? _.str.sformat(lang.CompareDocumentPublicationError, publicationError)
          : lang.IVDocumentLoadError;
        GlobalMessage.showMessage("error", errorMessage);
        this.destroy();
        return;
      }

      const docIdLeft = this.nodes.at(0).get('id');
      const docIdRight = this.nodes.at(1).get('id');

      this.api.addPublication(leftPublication, true, docIdLeft);
      this.api.addPublication(rightPublication, true, docIdRight);

      if (compareType === "text") {
        this.api.comparePublications(leftPublication.id, rightPublication.id, "text");
      } else {
        this.api.comparePublications(leftPublication.id, rightPublication.id);
      }

      setTimeout(() => {
        this.checkForMigration(this.model.connector, [docIdLeft, docIdRight]);
      }, 1000);
    },

    setLayout: function(isAnnotationDisable) {
      var layoutClone = JSON.parse(JSON.stringify(layout));
      if(isAnnotationDisable || this.isAnnotateDisabled()) {
        var removeAnnotationFeature = layoutClone.leftTabContainer && layoutClone.leftTabContainer.tabs;
        removeAnnotationFeature = removeAnnotationFeature.filter(function (value/*, index, arr*/) {
          if (_.contains(['MarkupPane', 'StampRasterPane', 'TakeoffPane'], value.component)) {
            return false;
          } else {
            return true;
          }
        });
        layoutClone.leftTabContainer.tabs = removeAnnotationFeature;
      }
      iViewerUtils.setHelpUrl(layoutClone).done(function() {
        this.api.setLayout(layoutClone);
      }.bind(this));
    },

    isAnnotateDisabled: function() {
      var disabled = false;
      if(isIVAnnotateDisabled) {
        disabled = true;
      } else if (!this.isRelatePermission) {
        disabled = true;
      }
      return disabled;
    },

    onChangeModel: function () {
      if (this.model.hasChanged('id') || this.model.hasChanged('version_number')) {
        this.render();
      }
    },

    onShow: function () {
      var me = this;
      this.blockActions();
      this.getPublicationDeferred = this._getPublication();
      iViewerUtils.getBravaIViewerConfiguration(this.model.connector).done(function(bravaIViewerConfigutation) {
        me.bravaIVConfiguration = bravaIViewerConfigutation;
        iViewerUtils.getAccessToken(me.model.connector).done(function(token) {
          me.bearerToken = 'Bearer ' + token;
          viewerUtils.isRelatePermission(me.model.connector, [me.model.get('id')]).done(function(permission) {
            me.isRelatePermission = permission;
            me._loadBravaViewerScripts();
          });
        }).fail(function () {
          GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
          me.destroy();
        });
      });
    },

    reloadViewer: function () {
      var me = this;
      this.clearViewer();
      this.migrationStatusTimer && clearInterval(this.migrationStatusTimer);
      this.hideMigrationStatusBar();
      this.blockActions();
      iViewerUtils.getAccessToken(this.model.connector).done(function(token) {
        me.bearerToken = 'Bearer ' + token;
        me.api.setHttpHeaders({'Authorization': me.bearerToken});
        if (me.documentIdAdded !== me.model.get('id')) {
          me.api.setSidebarOpen(false);
          viewerUtils.isRelatePermission(me.model.connector, [me.model.get('id')]).done(function(permission) {
            me.isRelatePermission = permission;
            me.setPublicationToViewer().always(function() {
              me.unblockActions();
              me.setLayout(false);
            });
          });
        } else {
          this._pageRendered();
          //this.viewerContentShow();
        }
      }).fail(function () {
        GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
        me.destroy();
      });
    },

    _getBravaIViewerConfiguration: function () {
      var configAPI = RestLinkrels.getLink(RestResources.getCurrentRepository().get("links"), RestLinkrels.D2_BRAVAIVIEWER_CONFIG_OPTIONS);

      return $.ajax(this.model.connector.extendAjaxOptions({
        url: configAPI,
        type: 'GET'
      }));
    },

    _getBravaViewerLoaderScript: function () {
      var viewerUrl = this.bravaIVConfiguration.brava_viewer_service_url + "/viewer/api/v1/viewers/brava-view-1.x/loader";
      return $.ajax({
        url: viewerUrl,
        type: 'GET',
        headers: {
          'Authorization': this.bearerToken
        }
      });
    },

    _loadBravaViewerScripts: function () {
      var me = this;
      //var ivScript = document.getElementById('IV-Script');
      var ivScript = $(this.el).find("#IV-Script");
      if (ivScript !== undefined && ivScript.length > 0) {
        var scriptText = ivScript.html();
        ivScript.remove();
        me._appendIVScript(scriptText);
        return;
      }
      this._getBravaViewerLoaderScript().done(function (response) {
        me._appendIVScript(response);
      }).fail(function (e) {
        GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
        me.destroy();
        console.error('User seems to be forbidden' + e);
      });
    },

    _getPublication: function () {
      var publicationAPIUrl = RestLinkrels.getLink(this.model.get("links"), RestLinkrels.D2_BRAVAIVIEWER_PUBLICATION);
      return $.ajax(this.model.connector.extendAjaxOptions({
        url: publicationAPIUrl,
        type: 'GET'
      }));
    },

    showExpandViewerButton: function () {
      this.api.unhideToolbarButtons(['expandViewerButtonButton']);
      this.api.hideToolbarButtons(['collapseViewerButtonButton']);
    },

    showCollapseViewerButton: function () {
      this.api.unhideToolbarButtons(['collapseViewerButtonButton']);
      this.api.hideToolbarButtons(['expandViewerButtonButton']);
    },

    _appendIVScript: function (scriptText/*, deferred*/) {
      var viewerScripts = document.createElement("script");
      viewerScripts.type = "text/javascript";
      viewerScripts.innerHTML = scriptText;
      viewerScripts.id = 'IV-Script';
      /* need to revisit  viewerScripts.onerror as this is not getting called in actual scanario */
      viewerScripts.onerror = function () {
        log.error('Error loading Viewer scripts');
      };
      $(this.el).append(viewerScripts);
    },

    _markupsDirtyEvent: function(markup) {
      if(markup.detail > 0) {
        this.isDirtyMarkup = true;
        this.needMarkupCountUpdate = true;
      }
      else {
        this.isDirtyMarkup = false;
      }
    },

    showSaveMarkupDialog: function() {
      var deferred = $.Deferred();
      var buttonOptions = {
        labelYes: lang.SaveMarkupDialogButtonYes,
        labelNo: lang.SaveMarkupDialogButtonNo,
        showNo: true,
        showCancel: true
      };

      ModalAlert.confirmQuestion(function (result) {
        if (result === true) {
          deferred.resolve();
        }
        if (result === false) {
          deferred.reject();
        }
      }, lang.SaveMarkupDialogBody, lang.SaveMarkupDialogHeader, {
        buttons: buttonOptions,
        modalClass: 'd2-iv-sm-dialog'
      });

      return deferred.promise();
    },

    checkForMigration: function(connector, documentIds) {
      var me = this;
      if(iViewerUtils.isMigrationEnabled()) {
        iViewerUtils.getMarkupMigrationStatusByObjectIds(connector, documentIds).done(function(statusData) {
          if(me.isMigrationStatusInProgress(statusData)) {
            me.setLayout(true);
            me.needMarkupCountUpdate = true;
            me.displayMigrationStatus('INPROGRESS', connector, documentIds);
          }
        });

      }
    },

    hideMigrationStatusBar: function() {
      $(this.el).find("#" + this.migrationStatusId).addClass('binf-hidden');
      $(this.el).find("#" + this.viewerId).removeClass('with-migration-status');
    },

    showMigrationStatusBar() {
      $(this.el).find("#" + this.migrationStatusId).removeClass('binf-hidden');
      $(this.el).find("#" + this.viewerId).addClass('with-migration-status');
    },

    displayMigrationStatus: function(status, connector, documentIds) {
      var me = this, region = new Marionette.Region({el: this.ui.markupMigration});
      var view = new MarkupMigrationView({
        status: status,
        reloadClick: function () {
          me.reloadViewer();
        }
      });
      this.showMigrationStatusBar();
      region.show(view);
      if(status == iViewerUtils.migrationStatusConstants.migrationStatusInprogress) {
        this.startPoolingMigrationStatus(connector, documentIds);
      }
    },

    startPoolingMigrationStatus: function(connector, documentIds) {
      this.migrationStatusTimer = setInterval(function () {
        iViewerUtils.getMarkupMigrationStatusByObjectIds(connector,documentIds).done(function(statusData) {
          if(this.isMigrationStatusComplete(statusData)) {
            this.displayMigrationStatus(iViewerUtils.migrationStatusConstants.migrationStatusComplete, connector, documentIds);
            clearInterval(this.migrationStatusTimer);
          } else if(this.isMigrationStatusFailed(statusData)) {
            this.displayMigrationStatus(iViewerUtils.migrationStatusConstants.migrationStatusFailed, connector, documentIds);
            clearInterval(this.migrationStatusTimer);
          }
        }.bind(this));
      }.bind(this), 10000);
    },


    isMigrationStatusInProgress: function(objectList) {
      var status = false;
      if(objectList && objectList.markupMigration && objectList.markupMigration.length> 0) {
        status = _.some(objectList.markupMigration, function(object) {
          return object.status === iViewerUtils.migrationStatusConstants.migrationStatusInprogress;
        });
      }
      return status;
    },

    isMigrationStatusComplete: function(objectList) {
      var status = false;
      if(objectList && objectList.markupMigration && objectList.markupMigration.length> 0) {
        status = _.every(objectList.markupMigration, function(object) {
          return object.status === iViewerUtils.migrationStatusConstants.migrationStatusComplete;
        });
      }
      return status;
    },

    isMigrationStatusFailed: function(objectList) {
      var status = false;
      if(objectList && objectList.markupMigration && objectList.markupMigration.length> 0) {
        status = _.some(objectList.markupMigration, function(object) {
          return object.status === iViewerUtils.migrationStatusConstants.migrationStatusFailed;
        });
      }
      return status;
    },

    isMigrationStatusTitleUpdateFailed: function(objectList) {
          var status = false;
          if(objectList && objectList.markupMigration && objectList.markupMigration.length> 0) {
            status = _.some(objectList.markupMigration, function(object) {
              return object.status === iViewerUtils.migrationStatusConstants.migrationStatusTitleUpdateFailed;
            });
          }
          return status;
        },

    clearViewer: function() {
      if (this.api.clearViewer) {
        this.api.clearViewer();
      }
    },

    closeViewer: function() {
      var dfd = $.Deferred();
      if(this.api) {
        this.destroy();
        dfd.resolve();
      } else {
        dfd.reject();
      }
      return dfd.promise();
    }
  });
});

csui.define('d2/commands/open.plugins/impl/iviewer/textcompareviewer.view',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'd2/utils/rest.linkrels',
  'dctmw/utils/rest.resources',
  'nuc/utils/log',
  'nuc/utils/url',
  'd2/controls/globalmessage/globalmessage',
  'd2/utils/server.query.utils',
  'd2/utils/widget.constants',
  'd2/commands/open.plugins/impl/iviewer/utils',
  'd2/commands/open.plugins/impl/viewer.utils',
  'd2/commands/open.plugins/impl/iviewer/default.view',
  'i18n!d2/commands/open.plugins/nls/localized.strings'
], function (_, $, Marionette, RestLinkrels, RestResources, log, Url, GlobalMessage,
             serverQueryUtils, widgetConstants, iViewerUtils, viewerUtils, DefaultView, lang) {
  'use strict';

  var ivWidgetConfiguration,
    intelligentViewerConfig,
    isIVAnnotateDisabled,
    layout,
    userDefaultWidgets,
    currentUser = RestResources.getCurrentUser();

  if (currentUser && !_.isEmpty(currentUser)) {
    userDefaultWidgets = currentUser.get('defaultWidgets');
  }
  if (userDefaultWidgets && !_.isEmpty(userDefaultWidgets)) {
    ivWidgetConfiguration = serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAIV, userDefaultWidgets[widgetConstants.DEFAULT.BRAVAIV]);
  }
  if (ivWidgetConfiguration && !_.isEmpty(ivWidgetConfiguration)) {
    intelligentViewerConfig = JSON.parse(ivWidgetConfiguration.widgetParams["iv_configuration_text_compare"]);
    isIVAnnotateDisabled = ivWidgetConfiguration.widgetParams["is_iv_disable_annotate_t_compare"];
  }

  if (isIVAnnotateDisabled) {
    var removeAnnotationFeature = intelligentViewerConfig.leftTabContainer.tabs;
    _.each(removeAnnotationFeature, function (item) {
      if (item !== undefined && item.component === 'MarkupPane') {
        removeAnnotationFeature.splice(removeAnnotationFeature.indexOf(item), 1);
      }
    });
  }
  if (intelligentViewerConfig && !_.isEmpty(intelligentViewerConfig)) {
    layout = _.defaults(
      {
        topToolbar: 'toolbarWithMarkupStuff',
        toolbarWithMarkupStuff: intelligentViewerConfig.toolbarWithMarkupStuff,
        mainContainer: [
          {component: 'TabContainer', layoutKey: 'leftTabContainer'},
          {component: 'TextCompareContainer'}
        ]
      }, intelligentViewerConfig);
  }

  var viewerClassName = 'd2-iv-text-compare';
  var appleMatches = navigator.userAgent.match(/(iPad)/i);
  if (appleMatches) {
    viewerClassName = 'd2-iv-text-compare-ipad';
  }

  var IVTextCompareViewer = DefaultView.extend({
    className: viewerClassName,

    constructor: function IVTextCompareViewer(options) {

      DefaultView.prototype.constructor.call(this, options);
    },

    onShow: function () {
      var me = this;
      this.blockActions();
      this.getPublicationDeferred = this._getPublication();
      iViewerUtils.getBravaIViewerConfiguration(this.model.connector).done(function(bravaIViewerConfigutation) {
        me.bravaIVConfiguration = bravaIViewerConfigutation;
        iViewerUtils.getAccessToken(me.model.connector).done(function(token) {
          me.bearerToken = 'Bearer ' + token;
          viewerUtils.isRelatePermission(me.model.connector, [me.nodes.at(0).get("id"), me.nodes.at(1).get("id")]).done(function(permission) {
            me.isRelatePermission = permission;
            me._loadBravaViewerScripts();
          });
        }).fail(function () {
          GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
          me.destroy();
        });
      }).fail(function () {
        GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
        me.destroy();
      });
    },

    reloadViewer: function () {
      var me = this;
      this.clearViewer();
      this.migrationStatusTimer && clearInterval(this.migrationStatusTimer);
      this.hideMigrationStatusBar();
      if(this.isPreviewMode) {
        !this.isAppliedMask() && this.trigger('apply:mask');
      }
      this.blockActions();
      iViewerUtils.getAccessToken(this.model.connector).done(function(token) {
        me.bearerToken = 'Bearer ' + token;
        me.api.setHttpHeaders({'Authorization': me.bearerToken});
        me.api.setSidebarOpen(false);
        viewerUtils.isRelatePermission(me.model.connector, [me.nodes.at(0).get("id"), me.nodes.at(1).get("id")]).done(function(permission) {
          me.isRelatePermission = permission;
          me.setPublicationToViewer().always(function() {
            me.unblockActions();
            me.setLayout(false);
          });
        });
      }).fail(function () {
        GlobalMessage.showMessage("error", lang.IVDocumentLoadError);
        me.destroy();
      });
    },

    addPublication: function(response) {
          this.addComparePublications(response, "text");
    },

    setLayout: function(isAnnotationDisable) {
      var layoutClone = JSON.parse(JSON.stringify(layout));
      if(isAnnotationDisable || this.isAnnotateDisabled()) {
        var removeAnnotationFeature = layoutClone.leftTabContainer && layoutClone.leftTabContainer.tabs;
        removeAnnotationFeature = removeAnnotationFeature.filter(function (value/*, index, arr*/) {
          if (_.contains(['MarkupPane', 'StampRasterPane', 'TakeoffPane'], value.component)) {
            return false;
          } else {
            return true;
          }
        });
        layoutClone.leftTabContainer.tabs = removeAnnotationFeature;
      }
      iViewerUtils.setHelpUrl(layoutClone).done(function() {
        this.api.setLayout(layoutClone);
      }.bind(this));
    },

    isAnnotateDisabled: function() {
      var disabled = false;
      if(isIVAnnotateDisabled) {
        disabled = true;
      } else if (!this.isRelatePermission) {
        disabled = true;
      }
      return disabled;
    },

    _getPublication: function () {
      var currRepoLinks = RestResources.getCurrentRepository().get('links');
      var publicationUrl = Url.combine(RestLinkrels.getLink(currRepoLinks, RestLinkrels.SELF), 'objects/iviewer-publication');
      var queryParam = {
        "object-ids": [this.nodes.at(0).get("id"), this.nodes.at(1).get("id")],
      }
      if (this.ivWidgetName && !_.isEmpty(this.ivWidgetName)) {
        queryParam["widget_name"] = this.ivWidgetName;
      }
      publicationUrl = Url.appendQuery(publicationUrl, Url.combineQueryString(queryParam));

      return $.ajax(this.model.connector.extendAjaxOptions({
        url: publicationUrl,
        type: 'GET',
        contentType: "application/json",
      }));
    }
  });

  return IVTextCompareViewer;
});

