csui.define('d2/commands/workflow/allworkflows.queryform',[
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'csui/models/command',
  'dctmw/controls/mixins/view.state/widget.view.state.mixin',
  'd2/utils/constants',
  'dctmw/utils/user.preference.storage',
  'd2/utils/contexts/factories/widget.view.state.factory',
  'i18n!d2/widgets/workflow.queryform/impl/nls/lang'
], function (require, _, $, CommandModel, WidgetViewStateMixin, constants, userPreference, WidgetViewStateModelFactory, lang) {
  'use strict';

  var AllWorkflowsQueryForm = CommandModel.extend({

    defaults: {
      signature: 'D2-AllWorkflowsQueryForm'
    },

    enabled: function () {
      return true;
    },

    execute: function (options) {
      var me = this;
      me.options = options || {};
      me.context = me.options.context;
      me._openWizard();
    },

    _openWizard: function () {
      var action = this;
      csui.require([
        'd2/controls/stepper.wizard/stepper.wizard.view'
      ], function (StepperWizard) {
        action._createWizardSteps().then(function (wizardSteps) {
          action._wizard = new StepperWizard({steps: wizardSteps, className: 'd2-wf-query-search-form', data: {}});
          action._wizard.show();
        });
      });
    },

    _createWizardSteps: function () {
      var me = this, dfd = $.Deferred();
      csui.require([
        'd2/widgets/workflow.queryform/impl/workflow.query.form.panel'
      ], function (WFQueryFormPanel) {
        var step = {
          id: 'wfqueryform',
          title: me.options.title,
          viewClass: WFQueryFormPanel,
          viewOptions: {
            context: me.options.context,
            widgetName: me.options.widgetName,
            workflowsReportingType: me.options.workflowsReportingType,
            'document-id_storeContainer': true,
            'document-id_restoreContainer': true
          },
          buttons: [
            {
              id: 'next',
              toolTip: lang.search,
              label: lang.search,
              disabled: function () {
                return this.searchButtonDisabled;
              },
              clickHandler: function () {
                this.validateForm(true,false).done(_.bind(function(isValid){
                  if(isValid){
                    var formValues, qParamData;
                    formValues = this.getFormValues();
                    if (formValues && !_.isEmpty(formValues)) {
                      qParamData = formValues ? JSON.stringify(formValues) : undefined;
                      var widgetViewStateModel = me.options.context.getObject(WidgetViewStateModelFactory);
                      widgetViewStateModel && widgetViewStateModel.set('qform-param', qParamData);
                      userPreference.saveLocalStorePreference(userPreference.StorageTypes.SEARCH_PANEL_VISIBILITY, constants.WidgetId.WORKFLOWS, true);
                      me.setViewStateWidgetName(me.options.widgetName);
                      me.options.context.viewStateModel.set('enabled', true);
                      me.options.applicationScope.set('id', 'allworkflows');
                      me.trigger('open:workflows:perspective');
                      me._wizard.close();
                    }
                  }
                },this));
              }
            }
          ]
        };
        var steparr = [];
        steparr.push(step);
        dfd.resolve(steparr);
      });
      return dfd.promise();
    }

  });
  _.extend(AllWorkflowsQueryForm.prototype, WidgetViewStateMixin);
  return AllWorkflowsQueryForm;
});

csui.define('d2/commands/viewer/direct.view.link',[
  'require',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'd2/utils/constants',
  'csui/models/command',
  'csui/utils/commandhelper',
  'd2/utils/server.query.utils',
  'd2/utils/widget.constants',
  'dctmw/utils/client.location'
], function(require, _, $, constants, CommandModel, CommandHelper, serverQueryUtils, widgetConstants, clientLocation){
  'use strict';

  const DirectViewLink = CommandModel.extend({
    defaults: {
      signature: 'D2-DirectView',
      command_key: 'D2-DirectView',
      scope: 'single'
    },

    enabled: function(status, options) {
      if (!CommandModel.prototype.enabled.call(this, status, options))
        return false;

      if(status && status.context && status.context.isEmbeddedMode === true) {
        return false;
      }
      var node = CommandHelper.getJustOneNode(status), enable = false,
          viewer = (status.data && status.data.viewer) ? status.data.viewer : '';
      if (node && status.nodes.length === 1) {
        enable = _.contains([constants.Types.DOCUMENT], node.get('type'));
        if(enable && !_.isEmpty(viewer)) {
          if(!(serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVACSR, viewer) ||
              serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAENTERPRISE, viewer) ||
              serverQueryUtils.getWidgetConfig(widgetConstants.D2.BRAVAIV, viewer))) {
            enable = false;
          }
        }
      }
      return enable;
    },

    execute: function(status/*, options*/) {
      var viewer = (status.data && status.data.viewer) ? status.data.viewer : '';
      const dfd = $.Deferred();
      var link = document.createElement("a");
      link.target = "_blank";
      if(viewer) {
        link.href = clientLocation.modularizeFragment(`viewer?node=${status.nodes.at(0).get('id')}&viewer-name=${viewer}`);
      } else {
        link.href = clientLocation.modularizeFragment(`viewer?node=${status.nodes.at(0).get('id')}`);
      }
      link.click();

      return dfd.resolve().promise();
    }
  });

  return DirectViewLink;
});


