csui.define('d2/widgets/task.aviator/controllers/chat.url',["require"], function (require) {
  return function getChatUrl(connector) {
    const url = connector.getConnectionUrl();
    if (require.defined("ot2cm/utils/ot2cm-utils")) {
      const ot2cmUtils = require("ot2cm/utils/ot2cm-utils");
      const subscriptionPath = ot2cmUtils.getSubscriptionPath();
      const origin = url.getOrigin();
      const baseUrl = subscriptionPath ? `${origin}/${subscriptionPath}` : origin;
      return `${baseUrl}/ai/v1/chat`;
    }
    return `${url.getCgiScript()}/api/v2/ai/chat`;
  };
});


csui.define('d2/widgets/task.aviator/controllers/chat.caller',["nuc/models/mixins/uploadable/uploadable.mixin", "d2/widgets/task.aviator/controllers/chat.url"], function (UploadableMixin, getChatUrl) {
  return function callChat(connector, body) {
    let data = JSON.stringify(body);
    let contentType;
    if (UploadableMixin.useJSON || UploadableMixin.mock) {
      contentType = "application/json";
    } else {
      data = `body=${encodeURIComponent(data)}`;
      contentType = "application/x-www-form-urlencoded";
    }
    return connector.makeAjaxCall({
      type: "POST",
      url: getChatUrl(connector),
      data,
      contentType
    });
  };
});


