        if ($(event.currentTarget).find('input[type="radio"]').length) {
          this.ui.menuItems.find('input[type="radio"]').prop('checked', false);
          $(event.currentTarget).find('input[type="radio"]').prop('checked', true);
          this._onSelectionChange();
        }
