csui.define('d2/widgets/navigation.header/controls/search/legacy.search.view',[
  'module',
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'csui/behaviors/keyboard.navigation/tabable.region.behavior',
  'd2/widgets/navigation.header/controls/search/search.view',
  'dctmw/utils/authenticators/session',
  'i18n!d2/widgets/navigation.header/controls/search/impl/nls/lang',
  'hbs!d2/widgets/navigation.header/controls/search/impl/legacy.search.view',
  'css!d2/widgets/navigation.header/controls/search/impl/legacy.search.view'
], function (module, _, $, Marionette, TabableRegionBehavior, SearchView, Session, lang, template) {
  'use strict';

  var LegacySearchView = Marionette.LayoutView.extend({
    className: 'd2-search-box',
    template: template,
    ui: {
      searchButton: '.d2-search-button',
      searchTextBox: '.d2-search-textbox'
    },
    regions: {
      searchTextBoxSection: '.d2-search-textbox'
    },

    behaviors: {
      TabableRegion: {
        behaviorClass: TabableRegionBehavior
      }
    },

    templateHelpers: function () {
      return {
        title: lang.searchToolTip
      };
    },


    currentlyFocusedElement: 'div.d2-search-interaction',

    constructor: function LegacySearchView(options) {
      var session = Session.get();
      Marionette.LayoutView.call(this, options);

      this.listenTo(session, 'begin', () => {
        this._hideSearchTextbox();
      });
    },


    events: {
      'click .d2-search-button': 'onClickSearch',
      'keydown .d2-search-interaction': 'onKeyDownSearch',
      'keydown .search-container input': 'inputTyped'
    },

    inputTyped: function (event) {
      if (event.keyCode === 27) {
        this._hideSearchTextbox();
      }
      event.stopPropagation();
    },

    onClickSearch: function (event) {
      this._clickSearchButton();
      event.stopPropagation();
    },

    onKeyDownSearch: function (event) {
      if (event.keyCode === 32 || event.keyCode === 13) {
        this._clickSearchButton();
        event.stopPropagation();
      }
    },

    _clickSearchButton: function () {
      if (this.searchFocused) {
        this._hideSearchTextbox();
      } else {
        this._showSearchTextbox();
      }
    },


    _showSearchTextbox: function () {
      var self = this;
      this.$el.parent().addClass('search-open');
      $(".binf-navbar-brand").removeClass("binf-navbar-collapse");
      this.ui.searchTextBox.show('blind', {direction: 'right'}, '200', function () {
        self.searchView.trigger('focus_text');
        // $(document).on('click.' + self.cid + ' keydown.' + self.cid, function (event) {
        //   var searchText = self.searchView.ui.input.val();
        //   if (searchText === undefined || searchText.trim().length === 0) {
        //     self._hideSearchTextbox();
        //   }
        // });
      });
      self.searchFocused = true;
      self._updateButtonIcon();
    },

    _hideSearchTextbox: function () {
      var self = this;
      this.ui.searchTextBox.hide('blind', {direction: 'right'}, '200', function () {
        self.$el.parent().removeClass('search-open');
        $(".binf-navbar-brand").addClass("binf-navbar-collapse");
        self.searchView.trigger('focus_text');
        //$(document).off('click.' + self.cid + ' keydown.' + self.cid);
      });
      self.searchFocused = false;
      self.searchView.trigger('reset_text');
      self._updateButtonIcon();
    },

    _updateButtonIcon: function () {
      if (this.searchFocused) {
        this.ui.searchButton.addClass('search-close-icon');
        this.ui.searchButton.removeClass('search-magnifier-icon');
      } else {
        this.ui.searchButton.addClass('search-magnifier-icon');
        this.ui.searchButton.removeClass('search-close-icon');
      }
    },
    onRender: function () {
      var context = this.options.context;
      this.searchView = new SearchView({
        context: context,
        parentView: this
      });
      this.getRegion('searchTextBoxSection').show(this.searchView);
      this._updateButtonIcon();
    }
  });
  return LegacySearchView;
});

csui.define('d2/widgets/table/type.attributes',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'dctmw/utils/authenticators/session',
  'd2/utils/contexts/factories/display.types.factory'
], function (_, $, Backbone, Session, DisplayTypesFactory) {

  // Cache the type/attribute data
  var typeAttributes;

  var TypeAttributeModel = Backbone.Model.extend({
    idAttribute: 'name'
  });

  var TypeAttributeCollection = Backbone.Collection.extend({
    model: TypeAttributeModel,
    comparator: 'label',

    deepClone: function () {
      return new TypeAttributeCollection(
        this.map(function (typeAttr) {
          return typeAttr.attributes;
        }));
    }
  });
  
  function getDisplayTypesCollection() {
    const context = Session.get().getContext();
    return context.getCollection(DisplayTypesFactory, {permanent: true, detached: true});
  }

  return {
    fetch: function (/*options*/) {
      var deferred = $.Deferred();

      if (typeAttributes) {
        deferred.resolve(typeAttributes.deepClone());
      } else {
        var displayTypes = getDisplayTypesCollection();
        displayTypes.ensureFetched({
          success: function () {
            var models = [];

            displayTypes.each(function (displayType) {
              var typeName = displayType.get('name'),
                typeLabel = displayType.get('label');
              models.push({
                name: typeName,
                label: typeLabel
              });

              var props = displayType.get('properties');
              _.each(props, function (prop) {
                models.push({
                  parent: typeName,
                  parentLabel: typeLabel,
                  name: typeName + '.' + prop.name,
                  label: prop.label
                });
              });
            });

            typeAttributes = new TypeAttributeCollection(models);

            for (var i = 0; i < typeAttributes.length; i++) {
              var typeAttr = typeAttributes.at(i),
                label = typeAttr.get('label'),
                prevLabel = '', nextLabel = '';

              if (i > 0) {
                prevLabel = typeAttributes.at(i - 1).get('label');
              }

              if (i < typeAttributes.length - 1) {
                nextLabel = typeAttributes.at(i + 1).get('label');
              }

              if (typeAttr.get('parent') && label !== prevLabel && label !== nextLabel) {
                typeAttr.unset('parentLabel');
              }
            }
            deferred.resolve(typeAttributes.deepClone());
          },
          error: function (err) {
            deferred.reject(err);
          }
        });
      }

      return deferred.promise();
    }
  };
});


