      // Skipping handleTableRowClick if args.target is these columns
      if ($(args?.target) && (($(args.target).hasClass('csui-node-type-icon')) ||
          ($(args?.target).hasClass('csui-checkbox')) ||
          ($(args.target).hasClass('csui-table-cell-name-link-text')) ||
          ($(args.target).find('span.csui-node-type-icon').length !== 0) ||
          ($(args.target).find('span.csui-table-cell-name-link-text').length !== 0))) {
        return;
      }

