csui.define('d2/widgets/virtual.document.explorer/impl/vdoc.command.controller.mixin',[
  'module',
  'nuc/lib/underscore',
  'nuc/utils/log',
  'd2/utils/vdoc.utils'
],function(module, _, log, vdUtil){
  'use strict';

  log = log(module.id);
  var logPrefix = 'VD CMD-Ctrl';

  return {
    mixin: function(prototype) {
      _.extend(prototype, {
        _beforeExecuteCommand: function(commandArgs, options) {
          options = options || {};
          var nodes = commandArgs.status && commandArgs.status.nodes,
              origSelectedNodes = commandArgs.status && commandArgs.status.d2OrigSelectedNodes;
          if(nodes) {
            var clonedNodes = nodes.map(function(nodeModel){
              var node = nodeModel.clone();
              node.origNode = nodeModel;
              log.debug('{0} - before execute - src - {1} - dest - {2}', logPrefix, vdUtil.getLogPrintableDetails(node.origNode), vdUtil.getLogPrintableDetails(node)) && console.log(log.last);
              node[vdUtil.MEM_TSTAMP] = nodeModel[vdUtil.MEM_TSTAMP];
              return node;
            });
            nodes.reset(clonedNodes, _.defaults({}, options, {silent: true}));
            /* Fix for DTWO-106503
               This issue is caused after cloning status.nodes in concurrency manager.
               For VD Tree view the Models objects inside the status.nodes also cloned.v
               Since both status.nodes and models inside the collection is cloned, "change" event mapping attached to the collection is lost.
               Because of this behavior, after a successful action, menu items are not updated.
               So restoring the cloned nodes in original status nodes.
             */
            origSelectedNodes && origSelectedNodes.reset(clonedNodes, _.defaults({}, options, {silent: true}));
          }
        },

        _afterExecuteCommand: function(commandArgs, options) {
          options = options || {};
          var nodes = commandArgs.status && commandArgs.status.nodes,
              origSelectedNodes = commandArgs.status && commandArgs.status.d2OrigSelectedNodes,
            origNodes = [];
          if(nodes) {
            nodes.each(function(nodeModel){
              log.debug('{0} - after execute - src - {1} - dest - {2}', logPrefix, vdUtil.getLogPrintableDetails(nodeModel), vdUtil.getLogPrintableDetails(nodeModel.origNode)) && console.log(log.last);
              vdUtil.syncToOriginalVDNode(nodeModel);
              origNodes.push(nodeModel.origNode);
              delete nodeModel.origNode;
            });
            nodes.reset(origNodes,  _.defaults({}, options, {silent: true}));
            // Fix for DTWO-106503
            origSelectedNodes && origSelectedNodes.reset(origNodes,  _.defaults({}, options, {silent: true}));
          }
        }
      });
      return prototype;
    }
  };
});

