    getErrorMessage(error) {
      let errorMessage;
      if (error) {
        if (_.isString(error)) {
          errorMessage = error;
        } else if (error.responseText) {
          errorMessage = utils.parseAjaxErrorAsString(error);
        } else if (error.message) {
          errorMessage = error.message;
        }
      }
      return errorMessage;
    }
    getCancelLabel() {
      return lang.CancelLabel;
    }
