        var viewStateModel = this.context.viewStateModel;
        viewStateModel && viewStateModel.unset(viewStateModel.CONSTANTS.URL_PARAMS) && viewStateModel.unset(viewStateModel.CONSTANTS.QUERY_STRING_PARAMS);
